import logging
import argparse

REPOS_DIR = os.path.join(os.path.dirname(__file__), "repos")
MEMORY_DIR = os.path.join(os.path.dirname(__file__), "memory")
REPOS_PER_RUN = 2
DEFAULT_AGENT = "claude"

GIT_NAME = os.environ.get("DAEMONCTL_GIT_NAME", "Eshaan0110")
