logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s  %(levelname)s  %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)
log = logging.getLogger()


def get_repos():
    repos = []
    for name in os.listdir(REPOS_DIR):
        path = os.path.join(REPOS_DIR, name)
        if os.path.isdir(path) and os.path.isdir(os.path.join(path, ".git")):
            repos.append((name, path))
    return repos


def load_memory(repo_name):
    path = os.path.join(MEMORY_DIR, f"{repo_name}.md")
    if os.path.isfile(path):
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    return None


def save_memory(repo_name, output):
    s = output.find("===MEMORY_START===")
    e = output.find("===MEMORY_END===")
    if s != -1 and e != -1:
        os.makedirs(MEMORY_DIR, exist_ok=True)
        with open(os.path.join(MEMORY_DIR, f"{repo_name}.md"), "w", encoding="utf-8") as f:
            f.write(output[s + 18:e].strip())
        log.info(f"  Memory saved")


def _git(path, args, env=None, check=True):
    r = subprocess.run(["git"] + args, cwd=path, env=env, text=True,
                       capture_output=True, check=False)
    if check and r.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
    return r.stdout


def _git_head(path):
    try:
        return _git(path, ["rev-parse", "HEAD"]).strip()
    except Exception:
        return None


def _clean_message(msg):
    out = []
    for line in msg.splitlines():
        low = line.strip().lower()
        if low.startswith("co-authored-by:"):
            continue
        if low.startswith("signed-off-by:") and any(k in low for k in BANNED_TRAILER_KEYWORDS):
            continue
        if any(sub in low for sub in BANNED_BODY_SUBSTRINGS):
            continue
        out.append(line)
    text = "\n".join(out).strip()
    while "\n\n\n" in text:
        text = text.replace("\n\n\n", "\n\n")
    return text


def _scrub_and_push(path, base_sha, env):
    """Rewrite any new commits (base_sha..HEAD) to strip Claude mentions, then push."""
    if not base_sha:
        return
    shas = [s for s in _git(path, ["log", "--reverse", "--format=%H", f"{base_sha}..HEAD"]).splitlines() if s]
    if not shas:
        return

    rebuild = False
    payloads = []
    for sha in shas:
        msg = _git(path, ["log", "-1", "--format=%B", sha])
        tree = _git(path, ["log", "-1", "--format=%T", sha]).strip()
        cleaned = _clean_message(msg)
        payloads.append((tree, cleaned))
        if cleaned.strip() != msg.strip():
            rebuild = True

    if rebuild:
        parent = base_sha
        for tree, msg in payloads:
            r = subprocess.run(
                ["git", "commit-tree", tree, "-p", parent, "-m", msg],
                cwd=path, env=env, text=True, capture_output=True, check=True,
            )
            parent = r.stdout.strip()
        _git(path, ["reset", "--hard", parent])
        log.info("  Rewrote commits to strip AI mentions")

    push = subprocess.run(
        ["git", "push", "--force-with-lease"], cwd=path, env=env,
        capture_output=True, text=True, timeout=60,
    )
    if push.returncode != 0:
        log.warning(f"  push failed: {push.stderr.strip()}")


def _log_new_commits(path, base_sha):
    if not base_sha:
        return
    try:
        out = _git(path, ["log", "--stat", "--format=%h %an <%ae>%n  %s", f"{base_sha}..HEAD"])
    except Exception:
        return
    log.info("  Commits landed:")
    for line in out.splitlines():
        log.info(f"    {line}")


def run_agent(name, path, agent_key):
    agent = AGENTS[agent_key]
    memory = load_memory(name)
    prompt = PROMPT_MEMORY.replace("{memory}", memory) if memory else PROMPT_FIRST
    mode = "incremental" if memory else "first run"

    print(f"\n{'='*50}")
    print(f"  {name} ({agent['name']}, {mode})")
    print(f"{'='*50}\n")

    env = os.environ.copy()
    env.update({
        "GIT_AUTHOR_NAME": GIT_NAME,
        "GIT_AUTHOR_EMAIL": GIT_EMAIL,
        "GIT_COMMITTER_NAME": GIT_NAME,
        "GIT_COMMITTER_EMAIL": GIT_EMAIL,
    })

    head_before = _git_head(path)

    try:
        result = subprocess.run(
            agent["build_cmd"](prompt),
            cwd=path, text=True, env=env,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            timeout=1200,
            encoding="utf-8", errors="replace",
        )
    except subprocess.TimeoutExpired as e:
        print(f"\n✗ {name} — timeout after 20 min")
        if e.stdout:
            print("--- last output ---")
            print(e.stdout[-2000:] if isinstance(e.stdout, str) else e.stdout.decode("utf-8", "replace")[-2000:])
        return
    except Exception as e:
        print(f"\n✗ {name} — subprocess error: {e}")
        return

    if result.returncode != 0:
        print(f"\n✗ {name} (exit {result.returncode})")
        if result.stdout:
            print("--- output ---")
            print(result.stdout[-2000:])
        return

    head_after = _git_head(path)

    if head_before == head_after:
        print(f"\n○ {name} — no commits this run")
        save_memory(name, result.stdout)
        return

    try:
        _scrub_and_push(path, head_before, env)
    except Exception as e:
        log.warning(f"  scrub/push failed: {e}")
    _log_new_commits(path, head_before)

    print(f"\n✓ {name}")
    save_memory(name, result.stdout)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--agent", "-a", choices=list(AGENTS.keys()), default=DEFAULT_AGENT)
    parser.add_argument("--repos", "-n", type=int, default=REPOS_PER_RUN)
    parser.add_argument("--list-agents", action="store_true")
    args = parser.parse_args()

    if args.list_agents:
        for k, v in AGENTS.items():
            print(f"  {k:10s} — {v['name']}")
        return

    repos = get_repos()
    chosen = random.sample(repos, min(args.repos, len(repos)))
    print(f"Today's repos: {', '.join(n for n, _ in chosen)}\n")

    for name, path in chosen:
        try:
            run_agent(name, path, args.agent)
        except Exception as e:
            print(f"\n✗ {name} — crashed: {e}")
            log.exception("run_agent crash")


if __name__ == "__main__":
    main()